-- Synthetic Risk-Alert Prioritization Pipeline Seed SQL
-- Deterministic export from CSV storage
PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

CREATE TABLE IF NOT EXISTS customers (
    customer_id TEXT,
    full_name TEXT NOT NULL,
    date_of_birth TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    city TEXT NOT NULL,
    segment TEXT NOT NULL CHECK (segment IN ('RETAIL', 'SALARIED', 'BUSINESS')),
    kyc_status TEXT NOT NULL CHECK (kyc_status IN ('VERIFIED', 'EXPIRED', 'PENDING')),
    kyc_risk_tier TEXT NOT NULL CHECK (kyc_risk_tier IN ('LOW', 'MEDIUM', 'HIGH')),
    kyc_verified_date TEXT,
    kyc_expiry_date TEXT,
    onboarding_date TEXT NOT NULL,
    PRIMARY KEY (customer_id)
);

CREATE TABLE IF NOT EXISTS merchants (
    merchant_id TEXT,
    merchant_name TEXT NOT NULL,
    category TEXT NOT NULL CHECK (category IN ('GROCERY', 'FUEL', 'ELECTRONICS', 'TRAVEL', 'DINING', 'UTILITIES', 'ENTERTAINMENT', 'HEALTHCARE', 'ECOMMERCE', 'GAMBLING', 'CRYPTO_EXCHANGE', 'JEWELRY')),
    risk_level TEXT NOT NULL CHECK (risk_level IN ('LOW', 'MEDIUM', 'HIGH')),
    city TEXT NOT NULL,
    onboarding_date TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('ACTIVE', 'INACTIVE')),
    PRIMARY KEY (merchant_id)
);

CREATE TABLE IF NOT EXISTS analysts (
    analyst_id TEXT,
    name TEXT NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('OPS_ANALYST', 'RISK_REVIEWER', 'SYSTEM_ADMIN')),
    status TEXT NOT NULL CHECK (status IN ('ACTIVE', 'INACTIVE')),
    PRIMARY KEY (analyst_id)
);

CREATE TABLE IF NOT EXISTS risk_rules (
    rule_id TEXT,
    rule_name TEXT NOT NULL,
    rule_type TEXT NOT NULL CHECK (rule_type IN ('DETECTION', 'ADJUSTMENT')),
    description TEXT NOT NULL,
    base_points INTEGER NOT NULL,
    parameters_json TEXT NOT NULL,
    effective_from TEXT NOT NULL,
    effective_to TEXT,
    status TEXT NOT NULL CHECK (status IN ('ACTIVE', 'INACTIVE')),
    PRIMARY KEY (rule_id)
);

CREATE TABLE IF NOT EXISTS devices (
    device_id TEXT,
    device_type TEXT NOT NULL CHECK (device_type IN ('ANDROID', 'IOS', 'WEB_BROWSER')),
    os_family TEXT NOT NULL CHECK (os_family IN ('ANDROID', 'IOS', 'WINDOWS', 'MACOS', 'LINUX')),
    fingerprint_hash TEXT NOT NULL,
    is_emulator INTEGER NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('ACTIVE')),
    first_registered_date TEXT NOT NULL,
    owner_customer_id TEXT,
    PRIMARY KEY (device_id),
    FOREIGN KEY (owner_customer_id) REFERENCES customers (customer_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS accounts (
    account_id TEXT,
    customer_id TEXT NOT NULL,
    account_type TEXT NOT NULL CHECK (account_type IN ('SAVINGS', 'CURRENT', 'SALARY')),
    open_date TEXT NOT NULL,
    close_date TEXT,
    status TEXT NOT NULL CHECK (status IN ('ACTIVE', 'DORMANT', 'CLOSED')),
    starting_balance REAL NOT NULL,
    overdraft_limit REAL NOT NULL,
    currency TEXT NOT NULL CHECK (currency IN ('INR')),
    PRIMARY KEY (account_id),
    FOREIGN KEY (customer_id) REFERENCES customers (customer_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS account_status_events (
    event_id TEXT,
    account_id TEXT NOT NULL,
    from_status TEXT CHECK (from_status IN ('ACTIVE', 'DORMANT', 'CLOSED')),
    to_status TEXT NOT NULL CHECK (to_status IN ('ACTIVE', 'DORMANT', 'CLOSED')),
    effective_ts TEXT NOT NULL,
    reason TEXT NOT NULL CHECK (reason IN ('OPENED', 'INACTIVITY_180D', 'REACTIVATED_BY_ACTIVITY', 'CLOSED_BY_CUSTOMER')),
    PRIMARY KEY (event_id),
    FOREIGN KEY (account_id) REFERENCES accounts (account_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS account_devices (
    account_id TEXT,
    device_id TEXT,
    first_seen_ts TEXT NOT NULL,
    last_seen_ts TEXT NOT NULL,
    txn_count INTEGER NOT NULL,
    link_status TEXT NOT NULL CHECK (link_status IN ('ACTIVE', 'INACTIVE')),
    PRIMARY KEY (account_id, device_id),
    FOREIGN KEY (account_id) REFERENCES accounts (account_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (device_id) REFERENCES devices (device_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS cases (
    case_id TEXT,
    primary_account_id TEXT NOT NULL,
    opened_ts TEXT NOT NULL,
    closed_ts TEXT,
    alert_count INTEGER NOT NULL,
    case_score INTEGER NOT NULL,
    priority TEXT NOT NULL CHECK (priority IN ('P1', 'P2', 'P3', 'P4')),
    status TEXT NOT NULL CHECK (status IN ('OPEN', 'ASSIGNED', 'UNDER_REVIEW', 'ESCALATED', 'CLOSED')),
    assigned_analyst_id TEXT,
    final_disposition TEXT CHECK (final_disposition IN ('TRUE_POSITIVE', 'FALSE_POSITIVE')),
    PRIMARY KEY (case_id),
    FOREIGN KEY (primary_account_id) REFERENCES accounts (account_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (assigned_analyst_id) REFERENCES analysts (analyst_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS transfer_links (
    transfer_id TEXT,
    source_account_id TEXT NOT NULL,
    dest_account_id TEXT NOT NULL,
    debit_txn_id TEXT NOT NULL UNIQUE,
    credit_txn_id TEXT NOT NULL UNIQUE,
    amount REAL NOT NULL,
    initiated_ts TEXT NOT NULL,
    settled_ts TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('SETTLED')),
    PRIMARY KEY (transfer_id),
    FOREIGN KEY (source_account_id) REFERENCES accounts (account_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (dest_account_id) REFERENCES accounts (account_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (debit_txn_id) REFERENCES transactions (txn_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (credit_txn_id) REFERENCES transactions (txn_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS transactions (
    txn_id TEXT,
    account_id TEXT NOT NULL,
    txn_ts TEXT NOT NULL,
    txn_type TEXT NOT NULL CHECK (txn_type IN ('POS_PURCHASE', 'ATM_WITHDRAWAL', 'UPI_PAYMENT', 'BILL_PAYMENT', 'NEFT_TRANSFER_OUT', 'TRANSFER_IN', 'SALARY_CREDIT', 'CASH_DEPOSIT', 'REFUND', 'CLOSURE_PAYOUT')),
    direction TEXT NOT NULL CHECK (direction IN ('DEBIT', 'CREDIT')),
    amount REAL NOT NULL,
    balance_before REAL NOT NULL,
    balance_after REAL NOT NULL,
    channel TEXT NOT NULL CHECK (channel IN ('MOBILE_APP', 'WEB', 'POS', 'ATM', 'BRANCH', 'UPI')),
    merchant_id TEXT,
    device_id TEXT,
    counterparty_account_id TEXT,
    transfer_id TEXT,
    PRIMARY KEY (txn_id),
    FOREIGN KEY (account_id) REFERENCES accounts (account_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (merchant_id) REFERENCES merchants (merchant_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (device_id) REFERENCES devices (device_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (counterparty_account_id) REFERENCES accounts (account_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (transfer_id) REFERENCES transfer_links (transfer_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS alerts (
    alert_id TEXT,
    rule_id TEXT NOT NULL,
    trigger_txn_id TEXT,
    account_id TEXT NOT NULL,
    customer_id TEXT NOT NULL,
    created_ts TEXT NOT NULL,
    risk_score INTEGER NOT NULL,
    severity TEXT NOT NULL CHECK (severity IN ('CRITICAL', 'HIGH', 'MEDIUM', 'LOW')),
    priority_rank INTEGER NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('OPEN', 'CLOSED_TRUE_POSITIVE', 'CLOSED_FALSE_POSITIVE')),
    case_id TEXT NOT NULL,
    explanation TEXT NOT NULL,
    PRIMARY KEY (alert_id),
    FOREIGN KEY (rule_id) REFERENCES risk_rules (rule_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (trigger_txn_id) REFERENCES transactions (txn_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (account_id) REFERENCES accounts (account_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (customer_id) REFERENCES customers (customer_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (case_id) REFERENCES cases (case_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS alert_evidence (
    alert_id TEXT,
    txn_id TEXT,
    role TEXT NOT NULL CHECK (role IN ('TRIGGER', 'SUPPORTING')),
    PRIMARY KEY (alert_id, txn_id),
    FOREIGN KEY (alert_id) REFERENCES alerts (alert_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (txn_id) REFERENCES transactions (txn_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS alert_score_components (
    alert_id TEXT,
    seq INTEGER,
    component_code TEXT NOT NULL,
    rule_id TEXT,
    points INTEGER NOT NULL,
    detail TEXT NOT NULL,
    PRIMARY KEY (alert_id, seq),
    FOREIGN KEY (alert_id) REFERENCES alerts (alert_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (rule_id) REFERENCES risk_rules (rule_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE IF NOT EXISTS analyst_actions (
    action_id TEXT,
    case_id TEXT NOT NULL,
    alert_id TEXT,
    analyst_id TEXT NOT NULL,
    action_type TEXT NOT NULL CHECK (action_type IN ('ASSIGN', 'REVIEW_START', 'ESCALATE', 'DISPOSITION', 'CLOSE')),
    disposition TEXT CHECK (disposition IN ('TRUE_POSITIVE', 'FALSE_POSITIVE', 'NEEDS_MORE_INFO')),
    action_ts TEXT NOT NULL,
    note TEXT NOT NULL,
    PRIMARY KEY (action_id),
    FOREIGN KEY (case_id) REFERENCES cases (case_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (alert_id) REFERENCES alerts (alert_id) DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY (analyst_id) REFERENCES analysts (analyst_id) DEFERRABLE INITIALLY DEFERRED
);

